 static Dictionary<string,object>D(object x){return x as Dictionary<string,object>??new Dictionary<string,object>();}static object V(Dictionary<string,object>d,string k){return d.ContainsKey(k)?d[k]:null;}static string S(Dictionary<string,object>d,string k){return Convert.ToString(V(d,k));}static IEnumerable<Dictionary<string,object>>A(object x){if(x is IEnumerable&&!(x is string)&&!(x is IDictionary))foreach(var item in (IEnumerable)x)yield return D(item);}static string J(object x){return new JavaScriptSerializer{MaxJsonLength=8388608,RecursionLimit=128}.Serialize(x);}static Dictionary<string,object>Read(string p){if(new FileInfo(p).Length>8388608)throw new InvalidDataException("Comparison exceeds8MiB");return new JavaScriptSerializer{MaxJsonLength=8388608,RecursionLimit=128}.Deserialize<Dictionary<string,object>>(File.ReadAllText(p,Encoding.UTF8));}
