 public EvidenceComparison(string root,Action back,string toolsRoot=null,bool readOnly=false){this.root=root;this.readOnly=readOnly||File.Exists(Path.Combine(root,".readonly-research-preview"));this.tools=toolsRoot??root;Dock=DockStyle.Fill;var bar=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,WrapContents=true};var close=new Button{Text="Назад в Research",AutoSize=true};close.Click+=(s,e)=>back();var rebuild=new Button{Name="RefreshEvidenceComparison",Text="Обновить сравнение из сохранённых файлов",AutoSize=true};rebuild.Click+=(s,e)=>Rebuild();bar.Controls.Add(close);bar.Controls.Add(rebuild);var ledgerButton=new Button{Name="OpenExactSourceLedger",Text="Исходные утверждения и условия — точные цитаты",AutoSize=true};ledgerButton.Click+=(s,e)=>OpenLedger();bar.Controls.Add(ledgerButton);var importReview=new Button{Name="ImportRevisionBoundReview",Text="Записать ревью выбранной ревизии из файла",AutoSize=true};importReview.Click+=(sender,args)=>ImportReview();importReview.Enabled=!this.readOnly;bar.Controls.Add(importReview);var idea=new Button{Name="ExportIsolatedIdeaPreview",Text="Экспорт идеи для обсуждения — без публикации",AutoSize=true};idea.Click+=(sender,args)=>ExportIdea();bar.Controls.Add(idea);bar.Controls.Add(new Label{Text="Слева:",AutoSize=true});bar.Controls.Add(left);bar.Controls.Add(new Label{Text="Справа:",AutoSize=true});bar.Controls.Add(right);var split=new SplitContainer{Dock=DockStyle.Fill,SplitterDistance=470};split.Panel1.Controls.Add(ltext);split.Panel2.Controls.Add(rtext);Controls.Add(split);Controls.Add(status);Controls.Add(bar);left.SelectedIndexChanged+=(s,e)=>ShowPair();right.SelectedIndexChanged+=(s,e)=>ShowPair();Reload();}
