 void ExportIdea(){try{var selected=left.SelectedItem as Row;if(selected==null)throw new InvalidOperationException("Сначала выберите кандидата слева.");string expectedRevision=S(D(V(D(V(selected.Data,"research_chain")),"revision_review")),"current_revision_sha256");if(String.IsNullOrWhiteSpace(expectedRevision))throw new InvalidOperationException("Обновите сравнение перед экспортом точной ревизии.");string exports=Path.Combine(root,"exports");Directory.CreateDirectory(exports);using(var file=new SaveFileDialog{Title="Неподтверждённая идея для обсуждения; публикация не разрешена",Filter="JSON|*.json",InitialDirectory=exports,FileName="idea-discussion-"+Guid.NewGuid().ToString("N")+".json",OverwritePrompt=true}){if(file.ShowDialog(this)!=DialogResult.OK)return;string issue;string python=PortableRuntime.Python(tools,"export",out issue);if(python==null)throw new InvalidOperationException(issue);PortableRuntime.Run(python,PortableRuntime.Quote(Path.Combine(tools,"social_idea_preview.py"))+" --root "+PortableRuntime.Quote(root)+" --candidate "+PortableRuntime.Quote(selected.Kind+":"+selected.Id)+" --expected-revision "+PortableRuntime.Quote(expectedRevision)+" --output "+PortableRuntime.Quote(file.FileName),tools,30000);status.Text="Локальный пример идеи сохранён. Пробелы источников и исторические FAIL сохранены; передачи в Social и публикации не было.";}}catch(Exception ex){status.Text="Экспорт идеи не выполнен: "+ex.Message;}}
