 void Reload(){left.Items.Clear();right.Items.Clear();try{var wrap=Read(Path.Combine(root,"comparison-state.json"));string payload=S(wrap,"payload_json");if(ProvenanceAudit.Sha(payload)!=S(wrap,"payload_sha256"))throw new InvalidDataException("Comparison payload hash mismatch");var data=new JavaScriptSerializer{MaxJsonLength=8388608,RecursionLimit=128}.Deserialize<Dictionary<string,object>>(payload);if(S(data,"schema")!="reveng-evidence-comparison-v1"||!Object.Equals(V(data,"winner_selected"),false)||!Object.Equals(V(data,"auto_admission"),false)||V(data,"verified_market_priority")!=null)throw new InvalidDataException("Comparison cannot select a winner or market priority");if(V(data,"research_chain")!=null){string verifyIssue;string verifyPython=PortableRuntime.Python(tools,"export",out verifyIssue);if(verifyPython==null)throw new InvalidOperationException(verifyIssue);PortableRuntime.Run(verifyPython,PortableRuntime.Quote(Path.Combine(tools,"comparison_data.py"))+" --root "+PortableRuntime.Quote(root)+" --verify",tools,30000);}var inputs=D(V(data,"inputs"));foreach(var p in inputs){if(!Allowed(p.Key))throw new InvalidDataException("Unexpected comparison input");string path=Path.Combine(root,p.Key);if(p.Value==null){if(File.Exists(path))throw new InvalidDataException("New input appeared; rebuild local comparison");}else if(!File.Exists(path)||LocalResearchController.Hash(path).ToLowerInvariant()!=Convert.ToString(p.Value))throw new InvalidDataException("Saved input changed; rebuild local comparison");}if(!inputs.ContainsKey("candidates.json")||!inputs.ContainsKey("research-output-cards.json"))throw new InvalidDataException("Required comparison inputs missing");var original=new Dictionary<string,Dictionary<string,object>>();var json=new JavaScriptSerializer{MaxJsonLength=8388608,RecursionLimit=128};foreach(var c in A(json.DeserializeObject(File.ReadAllText(Path.Combine(root,"candidates.json"),Encoding.UTF8))))original.Add("legacy_hypothesis:"+S(c,"candidate_id"),c);foreach(var c in A(V(Read(Path.Combine(root,"research-output-cards.json")),"cards")))original.Add("model_hypothesis:"+S(c,"research_id"),c);var notes=ManualHypotheses.Load(root);foreach(var n in notes.Errors.Count==0?notes.Records:new List<ManualHypotheses.Record>())original.Add("manual_hypothesis:"+n.Id,n.Data);var seen=new HashSet<string>();var rows=new List<Row>();foreach(var r in A(V(data,"rows"))){string kind=S(r,"kind"),id=S(r,"id"),key=kind+":"+id;if(!seen.Add(key)||!original.ContainsKey(key)||!Object.Equals(V(r,"winner"),false)||!Object.Equals(V(r,"auto_admission"),false))throw new InvalidDataException("Invented/duplicated candidate or automatic recommendation");foreach(var f in A(V(r,"source_texts"))){if(kind=="manual_hypothesis"){if(!Eq(V(f,"source_snapshot"),V(original[key],"source_snapshot"))||!Eq(V(f,"reference"),V(original[key],"reference"))||S(f,"text")!=S(D(V(original[key],"source_snapshot")),"text"))throw new InvalidDataException("Manual source/reference snapshot mismatch");}else ValidateField(f,inputs);}r["saved_alternative_assessments"]=V(D(V(data,"saved_alternative_assessments")),key);object unlinked=V(D(V(data,"research_chain")),"unlinked_claims");r["unlinked_claim_count"]=unlinked is IEnumerable&&!(unlinked is string)?((IEnumerable)unlinked).Cast<object>().Count():0;rows.Add(new Row{Data=r,Original=original[key],Id=id,Kind=kind});}if(!seen.SetEquals(original.Keys))throw new InvalidDataException("Comparison omits saved candidates");if(V(data,"manual_notes_error")!=null)status.Text="Manual drafts unavailable: "+S(data,"manual_notes_error")+"; source candidates remain readable; original bytes preserved.\r\n";foreach(var row in rows.OrderBy(r=>S(r.Original,"title"),StringComparer.OrdinalIgnoreCase).ThenBy(r=>r.Kind).ThenBy(r=>r.Id)){left.Items.Add(row);right.Items.Add(row);}left.SelectedIndex=right.SelectedIndex=-1;if(V(data,"manual_notes_error")!=null)status.Text+="\r\nManual drafts unavailable: "+S(data,"manual_notes_error")+"; original file preserved, omitted drafts are not zero or deleted.";status.Text="Снимок сохранённых файлов на момент загрузки; после правок обновите. Выберите две карточки вручную. Порядок — алфавит, не приоритет. Неподтверждённые баллы не используются; победитель не выбирается. Покупатель, независимый спрос и преимущество неизвестны. Нет новых источников, модели или внешних действий.";if(V(data,"manual_notes_error")!=null)status.Text+="\r\nManual notes unavailable; original bytes preserved: "+S(data,"manual_notes_error");ltext.Text=rtext.Text="Карточка не выбрана. Ничего не предложено как лучшая идея.";}catch(Exception ex){left.Items.Clear();right.Items.Clear();status.Text="Сравнение недоступно: "+ex.Message+". Исходные файлы не изменены. Нажмите обновление для локального пересчёта.";ltext.Text=rtext.Text="Подтверждённого сравнения или победителя нет.";}}
 void ValidateField(Dictionary<string,object>f,Dictionary<string,object>inputs){if(f.ContainsKey("source_snapshot"))return;string container=S(f,"container");if(!inputs.ContainsKey(container)||!Allowed(container)||S(f,"container_file_sha256")!=Convert.ToString(inputs[container]))throw new InvalidDataException("Field container not bound");var data=ReadContainer(container);var records=container=="candidates.json"?A(data).ToArray():A(V(D(data),"observations")).ToArray();Dictionary<string,object>row;if(container=="candidates.json"){var c=records.Single(x=>S(x,"candidate_id")==S(f,"candidate_id"));row=A(V(c,"observed_basis")).Single(x=>S(x,"evidence_id")==S(f,"evidence_id_local_to_container")&&S(x,"url")==S(f,"question_url")&&S(x,"source")==S(f,"source"));}else row=records.Single(x=>S(x,"evidence_id")==S(f,"evidence_id_local_to_container")&&S(x,"url")==S(f,"question_url")&&S(x,"source")==S(f,"source"));string field=S(f,"source_field"),key=S(f,"container_field");if(field=="title"&&key!="title"||field=="answer_text"&&key!="answer_text"||field=="observed_text"&&!new[]{"context_text","excerpt"}.Contains(key)||!new[]{"title","answer_text","observed_text"}.Contains(field))throw new InvalidDataException("Wrong source field");if(field=="observed_text"&&new[]{"public_topic_title","public_question_title"}.Contains(S(row,"kind")))throw new InvalidDataException("Title metadata cannot become original body");string text=S(row,key),url=field=="answer_text"?S(row,"answer_url"):S(row,"url");string expectedScope=field=="title"?"title_metadata_only":field=="answer_text"?S(row,"answer_scope"):row.ContainsKey("content_scope")?S(row,"content_scope"):"source_excerpt";object expectedDate=field=="answer_text"?V(row,"answer_observed_at"):field=="title"?V(row,"observed_at"):S(row,"context_observed_at")!=""?V(row,"context_observed_at"):V(row,"observed_at");object expectedCut=field=="title"?(row.ContainsKey("title_truncated")?V(row,"title_truncated"):false):field=="answer_text"?(row.ContainsKey("answer_text_truncated")?V(row,"answer_text_truncated"):false):row.ContainsKey("context_truncated")?V(row,"context_truncated"):row.ContainsKey("excerpt_truncated")?V(row,"excerpt_truncated"):false;if(S(f,"source_scope")!=expectedScope||!Eq(V(f,"captured_at"),expectedDate)||!Eq(V(f,"truncated"),expectedCut)||Convert.ToInt32(V(f,"field_codepoints"))!=ProvenanceAudit.Count(text))throw new InvalidDataException("Field scope/date/range metadata differs from saved source");var author=D(V(f,"reported_author"));object actualAuthor=V(row,field=="answer_text"?"answer_author_id":"author_id");if(text!=S(f,"text")||ProvenanceAudit.Sha(text)!=S(f,"field_sha256")||url!=S(f,"source_url")||S(row,"source")!=S(f,"source")||S(author,"namespace")!=S(row,"source")||!Eq(actualAuthor,V(author,"reported_id"))||S(author,"canonical_reported_id")!=CanonicalAuthor(S(row,"source"),actualAuthor)||S(f,"field_role")!=(field=="answer_text"?"community_answer":S(row,"kind")=="package_listing_not_demand"?(field=="title"?"software_listing_title_metadata":"software_listing_not_demand"):field=="title"?"original_title_metadata":"original_report_or_scoped_observation"))throw new InvalidDataException("Field text/URL/author/role differs from actual source container");foreach(var claim in A(V(f,"literal_claims")))foreach(var range in A(V(claim,"matching_ranges_codepoints"))){int a=Convert.ToInt32(V(range,"start")),b=Convert.ToInt32(V(range,"end"));if(a<0||b<=a||b>ProvenanceAudit.Count(text)||ProvenanceAudit.Slice(text,a,b)!=S(claim,"quote"))throw new InvalidDataException("Literal range mismatch");}}
 object ReadContainer(string name){string path=Path.Combine(root,name);if(new FileInfo(path).Length>8388608)throw new InvalidDataException("Source container exceeds8MiB");return new JavaScriptSerializer{MaxJsonLength=8388608,RecursionLimit=128}.DeserializeObject(File.ReadAllText(path,Encoding.UTF8));}

 static string ReviewDescription(Dictionary<string,object> link){var review=D(V(link,"revision_review"));var b=new StringBuilder("REVISION REVIEW: declared review only; identity not authenticated; no execution/publication authorization.\r\n");b.AppendLine("Current research revision: "+S(review,"current_revision_sha256")).AppendLine("Latest current declared decision: "+S(review,"decision")).AppendLine("Decision rationale: "+S(review,"decision_rationale")).AppendLine("Coverage: "+S(review,"coverage"));foreach(var open in A(V(review,"unclosed_conditions")))b.AppendLine("UNCLOSED FIELD "+S(open,"source_id")+" | "+S(open,"status")+" | "+J(V(open,"items")));b.AppendLine("Open questions: "+J(V(review,"open_questions"))).AppendLine("Source fields without annotations (not reviewed as complete): "+J(V(link,"source_fields_without_annotations")));foreach(var h in A(V(review,"history"))){var decision=D(V(h,"decision"));b.AppendLine("HISTORY - revision binding, not an active decision: "+S(h,"binding")+" | "+S(h,"revision_sha256")).AppendLine("Declared choice: "+S(decision,"choice")+" | rationale: "+S(decision,"rationale")).AppendLine("Decision basis: "+J(V(decision,"basis_claim_ids")));foreach(var field in A(V(h,"condition_reviews")))b.AppendLine("Field "+S(field,"source_id")+" | "+S(field,"status")+" | unresolved: "+J(V(field,"unclosed_conditions"))+" | rationale: "+S(field,"rationale"));b.AppendLine("Historical open questions: "+J(V(h,"open_questions")));}return b.ToString();}
 string Describe(Row row){if(row==null)return "Карточка не выбрана.";var c=row.Original;var b=new StringBuilder(readOnly?"HISTORICAL READ-ONLY ARCHIVE — current workspace unchanged.\r\n":"");b.AppendLine(DecisionStore.DescribeRecovery(root,row.Id,S(c,"review_revision_hash")));b.Append("Источник записи: "+row.Kind+" | ID: "+row.Id+"\r\n");b.AppendLine("Непроверенная гипотеза; это не подтверждённый покупатель/рынок. Балл, ожидаемая прибыль и автоматический победитель отсутствуют.");b.AppendLine(PriorityExplanation.DescribeResearchAssumptions(c));if(row.Kind=="legacy_hypothesis")b.AppendLine(OfficialObservationPresentation.Describe(root,row.Id,S(c,"review_revision_hash")));b.AppendLine("RESEARCH CHAIN: exact source links; unverified annotations; literal binding is not semantic proof; see exact revision, open conditions and declared decision below.").AppendLine(ReviewDescription(D(V(row.Data,"research_chain")))).AppendLine("SOURCE CONDITION ANNOTATIONS (not verified facts):").AppendLine(J(V(row.Data,"source_condition_annotations")));b.AppendLine("SAVED ASSISTANT ALTERNATIVE ASSESSMENTS — not new AI output or verified capability:").AppendLine(J(V(row.Data,"saved_alternative_assessments")));b.AppendLine("Imported annotations without recorded candidate association: "+S(row.Data,"unlinked_claim_count")+". See source ledger AI tab; not assigned to the selected candidate.");b.AppendLine("HISTORICAL STATUS (not approval): "+S(c,"status")).AppendLine("SAVED ALTERNATIVES / LIMITS (unverified): "+J(V(row.Data,"unverified_saved_alternatives")));foreach(string k in new[]{"title","buyer","buyer_role","problem_hypothesis","interpretation","solution_hypothesis"})if(S(c,k)!="")b.AppendLine(k+": "+S(c,k));b.AppendLine("Не хватает доказательств:").AppendLine(J(V(c,"missing_evidence"))).AppendLine("Риски: "+J(V(c,"risks"))).AppendLine("Плательщик/оплата, независимый спрос, пригодность альтернатив и преимущество: неизвестны.");if(row.Kind=="legacy_hypothesis")b.AppendLine(LegacyCandidateReviews.Describe(root,c));else if(row.Kind=="manual_hypothesis")b.AppendLine(ManualHypotheses.Load(root).Records.Single(n=>n.Id==row.Id).Text);else{b.AppendLine("Сохранённый ручной разбор (интерпретация): "+J(V(c,"assistant_source_review")));b.AppendLine("Проверка происхождения/формы, не истины: "+J(V(c,"output_review")));b.AppendLine("Старое предложение проверки — не разрешено этим экраном: "+S(c,"validation_step"));}b.AppendLine("Доступный сейчас шаг: прочитать конкретные сохранённые поля ниже, проверить буквальные фрагменты и условия, записать ручную гипотезу/критерий опровержения. Модель, GET, контакты, устройство/аккаунт, публикация и оплата не разрешаются сравнением.");b.AppendLine("Точные поля и отдельно заявленные авторы — не число независимых людей:");foreach(var source in A(V(row.Data,"source_texts"))){if(source.ContainsKey("source_snapshot")){b.AppendLine(J(source));continue;}b.AppendLine("Контейнер: "+S(source,"container")+" | E-ID внутри контейнера: "+S(source,"evidence_id_local_to_container")+" | поле: "+S(source,"source_field")).AppendLine(S(source,"source_url")).AppendLine("Область поля: "+S(source,"source_scope")+" | маркер усечения: "+J(V(source,"truncated"))+"; отсутствие флага не доказывает полноту удалённого источника.").AppendLine("Роль: "+Role(S(source,"field_role"))+" ["+S(source,"field_role")+"]"+" | автор (заявленные metadata): "+J(V(source,"reported_author"))).AppendLine("Дата захвата: "+EvidenceDates.Display(V(source,"captured_at"))+" | SHA256 поля: "+S(source,"field_sha256")).AppendLine("Фрагменты/диапазоны codepoint, смысл не подтверждён: "+J(V(source,"literal_claims"))).AppendLine(S(source,"text")).AppendLine();}return b.ToString();}
 void ShowPair(){var a=left.SelectedItem as Row;var b=right.SelectedItem as Row;ltext.Text=Describe(a);rtext.Text=Describe(b);if(a==null||b==null)return;if(a.Kind==b.Kind&&a.Id==b.Id){status.Text="Выбрана одна и та же карточка. Это не независимое сравнение. Победитель не выбирается.";return;}var sa=A(V(a.Data,"source_texts")).ToArray();var sb=A(V(b.Data,"source_texts")).ToArray();var urls=sa.Select(x=>S(x,"source_url")).Where(x=>x!="").Intersect(sb.Select(x=>S(x,"source_url"))).ToArray();var authors=sa.Select(x=>D(V(x,"reported_author"))).Where(x=>V(x,"canonical_reported_id")!=null&&S(x,"canonical_reported_id")!="").Select(x=>S(x,"namespace")+":"+S(x,"canonical_reported_id")).Intersect(sb.Select(x=>D(V(x,"reported_author"))).Where(x=>V(x,"canonical_reported_id")!=null&&S(x,"canonical_reported_id")!="").Select(x=>S(x,"namespace")+":"+S(x,"canonical_reported_id"))).ToArray();status.Text="Сравнение вручную, без ранжирования и победителя. Общих URL: "+urls.Length+"; совпадений заявленных author metadata в namespace: "+authors.Length+". Это не число людей; отсутствие совпадения не доказывает независимость. Проверяйте конкретные поля и неизвестное.";}
